  ["0a7e8f81"] = "Класове завдання мага. Бос «{npc:Obsidian Sentinel}» охороняє задній вхід до підземелля «{zone:Uldaman}». Далі — завдання «{quest:Mana Surges}» заради предмета «{item:Celestial Orb}» або «{item:Celestial Stave}».",
  ["a8f3bbea"] = "Принесіть предмет «{item:Infernal Orb}» до НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
